using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using Newtonsoft.Json.Linq;
using UnityEngine.TextCore.Text;

namespace Imoni.Editor
{
    /// <summary>Finite Home/settings glyphs are generated by Setup, before their first editor render.</summary>
    internal static class ImoniFontWarmup
    {
        private const string Root = "Assets/Imoni";
        internal static bool PrepareHomeSettings(FontAsset asset, string assetName)
        {
            if (assetName != "ZenMaruGothic-Black SDF") return false;
            JObject config = JObject.Parse(File.ReadAllText(Root + "/Config/GameConfig.json"));
            var text = new StringBuilder();
            // Restrict the source to this screen; do not serialize a play session's all-screen cache.
            string home = File.ReadAllText(Root + "/Resources/UI/Home.uxml");
            foreach (Match match in Regex.Matches(home, "(?:text|label|value|header|tooltip)=\"([^\"]*)\"")) text.Append(match.Groups[1].Value);
            text.Append("音: ONOFF音量−+0123456789%音量を上げる下げる通常モードエンドレス:連続成功で解放ホームランキング会員証チーム「鍋底同盟」 /人");
            text.Append(config["outGame"]["profile"]["defaultName"].Value<string>());
            foreach (string value in config["outGame"]["profile"]["initialOwnedFirst"].Values<string>()) text.Append(value);
            foreach (string value in config["outGame"]["profile"]["initialOwnedSecond"].Values<string>()) text.Append(value);
            text.Append(config["titles"]["default"]["first"].Value<string>());
            text.Append(config["titles"]["default"]["second"].Value<string>());
            // The supplied Zen Maru Gothic font has no U+79ED (秭) glyph. Leave that unit
            // to the existing runtime fallback; still fail on any missing Home/settings glyph.
            foreach (string unit in config["format"]["units"].Values<string>()) text.Append(unit.Replace("\u79ED", string.Empty));
            var codepoints = new SortedSet<uint>();
            string characters = text.ToString();
            for (int index = 0; index < characters.Length; index++)
            {
                uint point = (uint)char.ConvertToUtf32(characters, index);
                if (char.IsHighSurrogate(characters[index])) index++;
                if (point >= ' ') codepoints.Add(point);
            }
            asset.ReadFontAssetDefinition();
            bool populated = asset.TryAddCharacters(codepoints.ToArray(), out _, includeFontFeatures: true);
            // Unity 6 returns the original input in its missing array when every glyph already
            // exists, even though the call succeeds. Verify the resulting table for repeat Setup.
            uint[] missing = codepoints.Where(point => !asset.characterLookupTable.ContainsKey(point)).ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException("Home/settings font warmup is missing glyphs (TryAddCharacters=" + populated + "): " + string.Join(", ", missing.Select(point => "U+" + point.ToString("X4"))));
            // Keep Dynamic: names entered by the player remain unrestricted by this known-glyph set.
            return true;
        }
    }
}
